<?php
require_once __DIR__ . '/../../app/bootstrap.php';
$admin = require_admin(); $id = (int)($_GET['id'] ?? 0); $editing = $id > 0; $item = ['name'=>'','email'=>'','role_id'=>'','active'=>1];
if ($editing) { $stmt = db()->prepare('SELECT * FROM users WHERE id=?'); $stmt->execute([$id]); $item = $stmt->fetch() ?: null; if (!$item) { http_response_code(404); exit('Usuario no encontrado.'); } }
$roles = db()->query('SELECT id,slug,name FROM roles ORDER BY id')->fetchAll(); $error = flash('error'); layout_start($editing ? 'Editar usuario' : 'Nuevo usuario', $admin);
?><div class="toolbar"><div><p class="eyebrow">Administración central</p><h1><?= $editing ? 'Editar usuario' : 'Nuevo usuario' ?></h1><p><?= $editing ? 'Actualiza los datos y el rol de este acceso.' : 'Crea un acceso para un usuario de Metalrubber.' ?></p></div><a class="button secondary" href="<?= e(app_url('admin/users.php')) ?>">Volver</a></div><?= alert_html($error) ?><section class="content-card"><form method="post" action="<?= e(app_url('admin/user-save.php')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $editing ? $id : 0 ?>"><div class="form-grid"><label class="field"><span>Nombre completo</span><input name="name" value="<?= e($item['name']) ?>" required autocomplete="name"></label><label class="field"><span>Correo electrónico</span><input type="email" name="email" value="<?= e($item['email']) ?>" required autocomplete="email"></label><label class="field"><span>Rol</span><select name="role_id" required><?php foreach ($roles as $role): ?><option value="<?= (int)$role['id'] ?>" <?= (int)$item['role_id'] === (int)$role['id'] ? 'selected' : '' ?>><?= e($role['name']) ?></option><?php endforeach; ?></select></label><label class="field"><span><?= $editing ? 'Nueva contraseña (opcional)' : 'Contraseña' ?></span><input type="password" name="password" <?= $editing ? '' : 'required' ?> minlength="10" autocomplete="new-password"><?php if ($editing): ?><small class="form-note">Déjala en blanco para conservar la actual.</small><?php endif; ?></label></div><label class="field"><span>Estado</span><select name="active"><option value="1" <?= $item['active'] ? 'selected' : '' ?>>Activo</option><option value="0" <?= !$item['active'] ? 'selected' : '' ?>>Inactivo</option></select></label><div class="form-actions"><button type="submit">Guardar usuario</button><a class="button secondary" href="<?= e(app_url('admin/users.php')) ?>">Cancelar</a></div></form></section><?php layout_end();
